import React, { useCallback, useMemo, useRef, useState } from 'react';
import './App.css';

// The preview passes useState, useEffect, useMemo, useRef, useReducer, useContext,
// createContext and useCallback in as globals; write anything else as React.x.

export type FileNode = {
  id: string;
  name: string;
  children?: FileNode[];
};

// The project tree as the API returns it: unsorted. Treat it as given.
// A node with a children array is a folder, even when the array is empty.
export const FILES: FileNode[] = [
  { id: 'readme', name: 'README.md' },
  {
    id: 'src',
    name: 'src',
    children: [
      { id: 'index-tsx', name: 'index.tsx' },
      { id: 'styles', name: 'styles', children: [] },
      { id: 'app-tsx', name: 'App.tsx' },
      {
        id: 'components',
        name: 'components',
        children: [
          { id: 'tree-tsx', name: 'Tree.tsx' },
          { id: 'button-tsx', name: 'Button.tsx' },
        ],
      },
    ],
  },
  { id: 'package-json', name: 'package.json' },
  {
    id: 'public',
    name: 'public',
    children: [
      { id: 'index-html', name: 'index.html' },
      { id: 'favicon', name: 'favicon.ico' },
    ],
  },
];

// TODO: build the file explorer.
// - Render FILES as a tree: role="tree" on the list, role="treeitem" on every node,
//   aria-level, and data-path with the slash-separated path (src/components/Button.tsx).
// - Sort every level: folders first, then files, both by name ignoring case.
// - Folders start closed. Clicking a folder's .row toggles it and sets aria-expanded.
//   An open folder renders its children inside role="group"; an empty one shows "Empty folder".
// - Clicking a file's .row selects it: aria-selected="true" on that file only,
//   and .selection shows "Selected: <path>".
// - Keyboard: one tab stop (tabIndex 0) that follows focus. ArrowUp, ArrowDown, Home
//   and End move focus; ArrowRight opens a folder or enters it; ArrowLeft closes it or
//   moves to the parent; Enter toggles a folder or selects a file.
// - Collapse all closes every folder, and the tab stop must stay on a visible item.
export default function App() {
  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Project files</h1>
          <p className="subtitle">Arrow keys move, Right opens, Left closes, Enter selects.</p>
        </header>
        <div className="toolbar">
          <button type="button" className="collapse-all">
            Collapse all
          </button>
          <p className="selection">Nothing selected</p>
        </div>
        <ul className="tree">
          {FILES.map((node) => (
            <li key={node.id} className="item">
              <span className="row">
                <span className="name">{node.name}</span>
              </span>
            </li>
          ))}
        </ul>
      </section>
    </main>
  );
}

