:root {
  color-scheme: dark;
}

html, body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  place-items: center;
  padding: 24px;
  box-sizing: border-box;
}

.card {
  width: 100%;
  max-width: 520px;
  border-radius: 16px;
  border: 1px solid #1f2937;
  padding: 18px;
  display: grid;
  gap: 14px;
  box-sizing: border-box;
}

.header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
}

.collapse-all {
  border-radius: 999px;
  border: 1px solid #a3e635;
  background: transparent;
  color: #e5e7eb;
  padding: 6px 12px;
  font-size: 12px;
  cursor: pointer;
}

.selection {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
  overflow-wrap: anywhere;
}

.tree,
.tree ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.tree {
  border: 1px solid #1f2937;
  border-radius: 12px;
  padding: 6px 0;
}

.item {
  outline: none;
}

.row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding-right: 10px;
  font-size: 14px;
  cursor: pointer;
  border-radius: 8px;
}

.row:hover {
  background: #0f172a;
}

.item:focus-visible > .row {
  box-shadow: inset 0 0 0 2px #a3e635;
}

.item[aria-selected='true'] > .row {
  background: #1e293b;
  color: #f8fafc;
}

.icon {
  width: 14px;
  color: #9ca3af;
  text-align: center;
}

.item--folder > .row .name {
  font-weight: 600;
}

.empty {
  min-height: 28px;
  display: flex;
  align-items: center;
  font-size: 13px;
  font-style: italic;
  color: #9ca3af;
}
